INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tl_heart_wild','Ulfried''s masterpiece: a fang, a tusk, a claw, a pearl, an ember and an emerald heart, bound into one. The wild knows you now.\n\nLE +10, AU +10, Courage +1, Dodge +1, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmJRatCrown_name','Crown of the Rat Mother');
