INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_j_rat_crown','Mother Ratzinsky''s iron crown, shrunk to an amulet by the rust of the sewers. Disease and poison bow to it.\n\nLE +5, Willpower +2\nImmune to poison');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_ratzinsky','Mother Ratzinsky''s Iron Tooth');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_ratzinsky','An iron-hard incisor from the rat-mother of Ferdok. It still smells of the sewers.\n\nTrophy: Ulfried Pelzfeld, the trophy collector, will want it.');
