INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_c_ratzinsky','A cameo carved from her tooth. Sewers, cellars and pockets hold no secrets from you.\n\nSneak +2, Pick Pocket +2, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_cockroach','Carapace of the Gentle Sow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_cockroach','A shard of the giant cockroach that terrorised the Gentle Sow. The innkeeper wants it framed.\n\nTrophy: Ulfried Pelzfeld, the trophy collector, will want it.');
