INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_c_cockroach','Tavern-Brawler''s Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_c_cockroach','A ring of cockroach shell. Nothing in a tavern can hurt you any more, not even the stew.\n\nAU +5, Willpower +3\nImmune to poison');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_oracle_eye','Oracle Spider''s Eye');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_oracle_eye','A faceted green eye from the emerald spider that lairs beneath the oracle of Ferdok.\n\nTrophy: Ulfried Pelzfeld, the trophy collector, will want it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCOracle_name','Seer''s Eye Pendant');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCOracle_short','Seer''s Eye Pendant');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCOracle_long','Intuition +1, Perception +3');
