INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_c_oracle','The oracle spider''s eye in silver. You notice things a moment before they happen.\n\nIntuition +1, Perception +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_marascan_claw','Marascan Crab Claw');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_marascan_claw','A claw of the Marascan giant crab of Ferdok harbour, big enough to cut an oar in half.\n\nTrophy: Ulfried Pelzfeld, the trophy collector, will want it.');
