INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_c_marascan','A ring cut from the claw. Blows glance off you like waves off the pier.\n\nParry +1, AU +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_evil_heartwood','Heartwood of the Evil Tree');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_evil_heartwood','Black, oily heartwood from the evil tree of Moorbridge. It is still whispering.\n\nTrophy: Ulfried Pelzfeld, the trophy collector, will want it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCEvilTree_name','Witchwood Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCEvilTree_short','Witchwood Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCEvilTree_long','Magic resistance +2, AE +5');
