INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_c_evil_tree','A sliver of the whispering wood. It listens to spells, and argues with them.\n\nMagic resistance +2, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_mule_bell','Bell of the Undead Mule');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_mule_bell','The cracked bell of the undead mule of Moorbridge. It rings on its own at midnight.\n\nTrophy: Ulfried Pelzfeld, the trophy collector, will want it.');
