INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCMule_long','Constitution +1, Willpower +3, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_c_mule','Mule-Bell of Stubbornness');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_c_mule','The mule refused to stay dead. Now you refuse things too. Mostly reasonable advice.\n\nConstitution +1, Willpower +3, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_vault_mandible','Vault Spider''s Mandible');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_vault_mandible','A mandible of the emerald spider in the vaults of Castle Grimmzahn.\n\nTrophy: Ulfried Pelzfeld, the trophy collector, will want it.');
