INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_linnorm_heart','The heart of the Linnorm of the Stinking Caves near Tallon, dried hard as wood. It still feels warm.\n\nTrophy: Ulfried Pelzfeld, the trophy collector, will want it.');
