INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_c_linnorm','You carry the courage of a creature that fought you to the last.\n\nCourage +2, LE +10');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_ogre_tusk','Ogre Chief''s Tusk');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_ogre_tusk','A yellow tusk of the Ogre Chief of Tallon, as thick as a wrist.\n\nTrophy: Ulfried Pelzfeld, the trophy collector, will want it.');
