INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_c_ogre','Heavy, crude and immensely strong, like its first owner. Swing hard; aim later.\n\nStrength +1, LE +10, Attack -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_dragon_eye','Eye of Japhgur');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_dragon_eye','The eye of the Purplewyrm Japhgur, the size of a shield boss. It never closes.\n\nTrophy: Ulfried Pelzfeld, the trophy collector, will want it.');
