INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCJaphgur_short','Wyrmeye Amulet');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCJaphgur_long','Intuition +2, Magic resistance +3, Dodge +1; Immune to burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_c_japhgur','Wyrmeye Amulet');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_c_japhgur','The dragon''s eye in gold. Fire, magic and blades all seem slower now.\n\nIntuition +2, Magic resistance +3, Dodge +1\nImmune to burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_greymaw_fang','Greymaw''s Fang');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_greymaw_fang','The great fang of Greymaw, alpha of the moon-mad pack of the Dark Forest. Silver light still clings to it.\n\nTrophy: Ulfried Pelzfeld, the trophy collector, will want it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCMadpack_name','Moon-Mad Totem');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCMadpack_short','Moon-Mad Totem');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCMadpack_long','Courage +1, AU +5, Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_c_madpack','Moon-Mad Totem');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_c_madpack','Greymaw''s fang on a thong of moon sinew. The pack''s madness is gone; its courage stayed.\n\nCourage +1, AU +5, Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_spirit_claw','Claw of the Elder Spirit');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_spirit_claw','A claw of pale, living wood from the Elder Spirit-Bear of the Deeps of Gruldur. Lightning crawls along its grain.\n\nTrophy: Ulfried Pelzfeld, the trophy collector, will want it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCSpiritbear_name','Totem of the Elder Bear');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCSpiritbear_short','Totem of the Elder Bear');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCSpiritbear_long','Constitution +2, Magic resistance +2, LE +15, AU +10');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_c_spiritbear','Totem of the Elder Bear');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_c_spiritbear','The spirit of the oldest bear walks beside you. Lightning knows your name.\n\nConstitution +2, Magic resistance +2, LE +15, AU +10');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_harpy_plume','Harpy Queen''s Crown-Plume');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_harpy_plume','The long storm-grey crown feather of the Harpy Queen of Tallon. It still smells of rain and blood.\n\nTrophy: Ulfried Pelzfeld, the trophy collector, will want it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCHarpyqueen_name','Featherfall Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCHarpyqueen_short','Featherfall Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCHarpyqueen_long','Agility +2, Dodge +1, Ranged combat +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_c_harpyqueen','Featherfall Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_c_harpyqueen','A gold ring wrapped in one grey plume. You move like wind across a cliff.\n\nAgility +2, Dodge +1, Ranged combat +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_golem_heart','Golem Heartstone');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_golem_heart','The rune-stone heart of a stone golem from Aldessia''s chambers in Murolosh.\n\nTrophy: Ulfried Pelzfeld, the trophy collector, will want it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCGolem_name','Heartstone Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCGolem_short','Heartstone Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCGolem_long','Constitution +2, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_c_golem','Heartstone Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_c_golem','A ring of golem stone. You are a little more stone yourself.\n\nConstitution +2, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_cyclops_gem','Cyclops Eye-Gem');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_cyclops_gem','The gem that sat in the single eye socket of the cyclops skeleton in the Deeps of Gruldur.\n\nTrophy: Ulfried Pelzfeld, the trophy collector, will want it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCCyclops_name','Cyclops''-Eye Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCCyclops_short','Cyclops''-Eye Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCCyclops_long','Dexterity +2, Intuition +1, Bow +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_c_cyclops','Cyclops''-Eye Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_c_cyclops','One eye sees further than two. Your shots fly true.\n\nDexterity +2, Intuition +1, Bow +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_grolm_shard','Grolm King''s Crown-Shard');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_grolm_shard','A shard of the Grolm King''s crown, hidden in his treasure chests behind the Fire Falls.\n\nTrophy: Ulfried Pelzfeld, the trophy collector, will want it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCGrolm_name','Grolm King''s Signet');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCGrolm_short','Grolm King''s Signet');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCGrolm_long','Charisma +2, Haggle +5, Fast Talk +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_c_grolm','Grolm King''s Signet');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_c_grolm','Grolms bargain for a living. This ring has never lost a bargain.\n\nCharisma +2, Haggle +5, Fast Talk +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mo_spiritbear','A bear of pale, living wood, older than the dwarves. Lightning crawls over it, and the dark answers when it roars.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookatdead_arm_mo_spiritbear','Dead The Elder Spirit-Bear');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mo_spiritbear','The Elder Spirit-Bear');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mo_spiritbear_esc1','A bear of pale wood and lightning. It follows the Elder Spirit.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookatdead_arm_mo_spiritbear_esc1','Dead Spirit Bear');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mo_spiritbear_esc1','Spirit Bear');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mo_spiritbear_esc2','A bear of pale wood and lightning. It follows the Elder Spirit.');
