INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mo_spiritbear_esc2','Spirit Bear');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mo_spiritbear_esc3','A bear of pale wood and lightning. It follows the Elder Spirit.');
