INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mo_spiritbear_esc3','Spirit Bear');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mo_harpyqueen','A harpy twice the size of the others, crowned with long storm-grey plumes. Her flock answers when she sings.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookatdead_arm_mo_harpyqueen','Dead The Harpy Queen');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mo_harpyqueen','The Harpy Queen');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mo_harpyqueen_esc1','A harpy of the queen''s flock.');
