INSERT INTO _Locale ("LocaId","LocaText") VALUES ('3fa0cb05-0844-55c4-98be-a4c2d0ffdb2d','The Harpy Queen''s Song');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5df33c19-b128-5fff-9f26-6124d18727f8','The Harpy Queen sings, and her flock answers. Every verse of her song brings more of them.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a477033f-26cd-5b9a-8bf5-66818c43d68b','The Harpy Queen is silent for good.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('72eb995d-2b2b-56c5-a6fe-f0e2cd388122','The First Verse');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d7a6a686-eda8-5852-bd1c-39ba2ac703c4','She is singing to her flock.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('dc788c43-3778-55c4-a4a1-089faec110dc','More harpies answered her song, and her feathers hardened like armour.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('196ad0ad-c084-5b04-9f0b-3b86c83240e8','The Storm Shriek');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d6d72ca3-f5e2-5de0-b175-6dd78aeea8f1','Wounded, she is drawing breath for something worse.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('4417c7b9-4fb3-5f6a-9bb3-175be26c1955','She shrieked a flash of storm-light and flew into a frenzy.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ff9436b2-f59c-5c4e-97c5-b72af8e1d1eb','The Queen''s Court');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e2a64618-d175-5eb6-934a-e0dc6765f940','The Queen of the Marsh croaks, and the marsh answers. The whole court is coming.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('56c6273d-aa4d-5e4a-865a-edf3403f602d','The Queen of the Marsh is dead, and her court with her.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b052b6ff-0143-5612-8d2a-df096b17a54c','The Croak');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('f94fde68-f0aa-51a9-98d1-b244b982bea1','She swells up, ready to call.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2403688b-eca9-59bc-96af-0289caa78b85','Three more toads crawled out of the mud, and her croak made my arm heavy as lead.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('688bbe6f-6cb1-5efd-95a0-e0456fdaf789','The Gorge');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('6930738d-892b-5abf-8141-1344e40af57b','Wounded, she sinks half into the mud.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('86c5d42b-29da-57d0-9f2b-0c34c6c04aea','She gorged on the marsh, closed her wounds and hardened her hide.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e716447b-6c27-5920-85e6-03fb91f6c9c5','The Elder''s Roar');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('eb613e12-14db-5057-9367-718a032f9429','Ashpelt the Elder is hurt, and the forest is listening.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('89145746-b6d5-5645-8054-152aab4efcae','Ashpelt the Elder is dead.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2b5f3178-297d-5437-9f49-68751af7c567','The Call of the Forest');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8fcf46f5-2012-5508-9387-61dca398d3e7','He rears up and roars at the trees.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('f64208ad-9f4b-52b7-a686-2bfc195172fa','Two spirits of the forest and three bears answered his roar.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('name_arm_q_beast_ledger','Ulfried''s Ledger of Beasts');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_q_beast_ledger','Ulfried''s Ledger of Beasts');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('text_arm_q_beast_ledger','THE GRAND COLLECTION OF ULFRIED PELZFELD\n\nMother Ratzinsky ruled the cellars of Ferdok for nine winters. Her iron tooth hangs over my door; no rat has come near since.\n\nThe cockroach of the Gentle Sow ate three hams, a barrel of pickles and a tax collector''s ledger. Only the ledger was missed.\n\nThe spider below the oracle wove its webs in the shape of prophecies. None of them came true. Spiders are poor seers.\n\nThe Marascan crab cut a fishing boat in two in the year of the long winter. The fishermen still owe it a boat.\n\nThe evil tree of Moorbridge whispered every night. I wrote down what it said. I burned what I wrote.\n\nThe undead mule refused to die, to move, or to carry anything. In this it was no different from a living mule.\n\nThe spider of Grimmzahn''s vaults grew fat on orcs. The orcs, to be fair, grew fat on everything else.\n\nThe Linnorm of the Stinking Caves was old when Tallon was a village. It is the only beast in this book I am sorry we killed.\n\nThe Ogre Chief of Tallon wore his tusks as a crown and his enemies as a cloak. You have neither now. Good.\n\nJaphgur the Purplewyrm. Its eye watched Tallon burn twice. It will not watch again. I have it, in a jar, and it still watches me.\n\nA storm came down on the western woods and the witches'' wolves went mad, all fifteen. The grey alpha''s fang still shines at night, as if the moon were inside it.\n\nBelow the mountains a bear older than the dwarves turned into a spirit and forgot to die. It was not angry. It was only very, very old.\n\nThe Harpy Queen of Tallon sang to her flock before every hunt. The hunters of Tallon learned the song, and learned to run when they heard it.\n\nAldessia''s golems were built to guard and nothing else. The heartstone is warm, as if it still remembers its orders.\n\nThe cyclops of Gruldur fell before the dwarves had a name. Its eye-gem shows a forge that no longer exists.\n\nThe Grolm King hoarded crowns he never wore. This shard is from the only one he loved. I will not tell you how I know.\n\nAll of it brought by one hunter. I have stopped telling people who. They would not believe me anyway.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCMantle_name','Mantle of a Thousand Trophies');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCMantle_short','Mantle of a Thousand Trophies');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCMantle_long','LE +10, AU +10, Courage +1, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_c_mantle','Mantle of a Thousand Trophies');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_c_mantle','Ulfried''s life''s work: a mantle stitched with a scrap of every legend you brought him. Hunters bow when you pass.\n\nLE +10, AU +10, Courage +1, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_ulfried','Ulfried Pelzfeld, Trophy Collector');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d22a78d4-c613-5e5a-8d56-9058caf11170','Ah, a traveller with sharp eyes and, I hope, a sharp knife! Ulfried Pelzfeld, collector of trophies, curiosities and anything with teeth. Avestrue''s woods are full of wolves, and wolves are full of fangs.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2f449c9c-f3b1-5800-a2a1-e569be45bdff','Back again, <FirstName>! Did you bring me something with teeth?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('9e997063-3501-525d-ac2f-8767d91211f1','Do you have work for me?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('350aa0c6-6e86-5a9e-abc2-20013570d884','Bring me two wolf fangs. Skin the wolves around Avestrue; a furrier''s knife helps, and Owlstone sells one, as do I. White Fur herself has a fine pair, and more besides. I pay in silver, and in something better.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('0387273f-96a4-5002-96af-423696e7e57e','Two wolf fangs. Consider it done.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('78e67433-1f07-5174-ae4f-bc086ac3993c','Splendid! Mind the white one. She is bigger than the stories.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('eb5c1d0c-1471-5646-a5de-f9302df3f8fa','I have your wolf fangs.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('17347422-570b-5916-b713-cab862a34cd8','Beautiful fangs! Here: a necklace I made from the last pair, and some silver. And now that I know you can hunt, I have bigger plans for us. Oh, and between us: the chickens of Avestrue are not what they seem.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('aceb8d77-08ed-5f53-95e4-51c4e419e81b','Bigger plans?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('7f39dc76-f8e4-571c-97de-46a3ad9e5365','Five beasts, friend. Five legends every hunter tells at the fire, and nobody has a trophy of. A great boar, an old bear, a queen who croaks, a mother who glows, and one more I will not name until you are ready for her. Where exactly? If I knew, I would be rich. Bring me their trophies and I will make you talismans no king owns.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2bb90573-2ba7-5c35-8eb6-fd6401e1eda4','I will hunt your legends.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('00e1f840-0526-5354-a5fa-dfcf9c15fb54','Ha! Then I had better start sharpening my tools. Bring them one at a time; each is a masterpiece.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('17ffe487-21c6-5d03-bb8c-a3b1f78a9425','What else does a collector collect?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('3ef2f84d-9624-5318-9938-d51807e0d2d4','Everything that has ever made a town lock its doors! Thirteen of them. Some are closer than you think: in the city, under it, and in its water. Others you will meet only if your road goes far, and I think it will. I follow the hunters, so look for me wherever the game gets bigger. Bring me one trophy of each. Your journal will keep my riddles.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b6a26a69-d556-5edc-9238-b2496b735db8','Your Grand Collection. I will fill it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d0195d22-d526-541b-bbb9-ed38b9ada057','Then we shall be famous! Or eaten. Probably famous.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8a6f2c50-03db-5f77-af9c-cbc91fa802e0','Any advice on finding your monsters?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('3215e0ab-206e-5f21-8c54-cc3e04c2ddfd','Advice? Listen to frightened people. Wherever doors are locked at night and children are told not to go somewhere, one of my beasts is close. Start with the city, and keep your eyes open on the road. My riddles are in your journal.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('12bc4c63-0e85-5394-a2d1-2e35c48e1913','Old Grimtusk is dead. I brought you this: Grimtusk''s Tusk.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ba040654-693b-57ae-a479-57b742337d7c','Old Grimtusk! By Firun''s beard, you really did it. Give me a moment... there. The Grimtusk Charm. Wear it with pride.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('425d2a46-a22d-50af-897b-211c5f160553','Ashpelt the Elder is dead. I brought you this: Ashpelt''s Claw.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('934e40c9-464d-5a92-a11e-b8ac71bb3c81','Ashpelt the Elder! By Firun''s beard, you really did it. Give me a moment... there. The Ashpelt''s Talisman. Wear it with pride.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ec1ba3ec-86f5-572b-a463-b26ecc67a47d','Queen of the Marsh is dead. I brought you this: Marsh Pearl.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('3a7f9521-04c6-569c-968f-fb3e93393e01','Queen of the Marsh! By Firun''s beard, you really did it. Give me a moment... there. The Marsh Pearl Ring. Wear it with pride.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('59080624-b636-51ff-9cb3-904ef496b349','The Ember Queen is dead. I brought you this: Ember Crown.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e314d735-6ba1-5811-b966-f0361bb9c2ae','The Ember Queen! By Firun''s beard, you really did it. Give me a moment... there. The Ember Crown Pendant. Wear it with pride.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('028ec14f-2528-5d1b-8b13-9a9e35863c1b','The Broodmother is dead. I brought you this: Broodmother''s Heart.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('bfbb3407-81dc-5a76-9b5f-6a3b25ccaf93','The Broodmother! By Firun''s beard, you really did it. Give me a moment... there. The Broodmother''s Heart. Wear it with pride.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('966f00b9-0335-520b-ac33-1a3e31fd33df','For your Grand Collection: Mother Ratzinsky''s Iron Tooth.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d292655b-1a82-5752-94a9-9576fa683c08','Oh! Oh, look at it. Into the collection it goes, with a label in my best hand. For you: the Rat-Queen''s Cameo, and a purse for the road.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('34e3bffa-2034-5539-b5fb-449e6e8b28d1','For your Grand Collection: Carapace of the Gentle Sow.');
