INSERT INTO _Locale ("LocaId","LocaText") VALUES ('17fc40f6-e679-5f43-8caa-c3a92b854d6e','For your Grand Collection: Cyclops Eye-Gem.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('83b9f675-8bcd-5557-9c1f-88abca167f43','Oh! Oh, look at it. Into the collection it goes, with a label in my best hand. For you: the Cyclops''-Eye Ring, and a purse for the road.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e2f96f42-8009-5710-b572-8ac49d7f159a','For your Grand Collection: Grolm King''s Crown-Shard.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a3a56f1b-2aed-543f-ba8b-583a22ed4687','Oh! Oh, look at it. Into the collection it goes, with a label in my best hand. For you: the Grolm King''s Signet, and a purse for the road.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('09a08cb0-b1d3-5ccf-ba6f-5b281f3ca545','That was the last of your five legends.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('358d9dfe-6042-5a46-bae9-e0de9d6f694a','All five. Nobody will believe me, and I do not care. I kept a piece of each; this is the best thing I have ever made. Take it. The Heart of the Wild. And some gold, because legends still have to eat.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('80865ac7-aced-51e1-962e-f3057e725b05','That completes your Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('22ba9c4e-2009-5dad-9e5a-9c3dca0aad10','Complete. The Grand Collection of Ulfried Pelzfeld, and every piece in it brought by one hunter. I sewed a scrap of each into this mantle. Wear it, and every hunter from here to the deepest dwarf hall will know who you are.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('1c420536-2344-581c-9c67-ff3dd439f8fb','Show me your wares.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('fcea587f-2ac9-51b9-a545-53dbdfbe3beb','Farewell, Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_ulfried_f','Ulfried Pelzfeld, Trophy Collector');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('9544721d-0192-591f-bcda-81097dacc2c7','Ulfried Pelzfeld, collector of trophies! I follow the hunters, and the hunters follow the money, so here I am in Ferdok. Bring me anything with teeth, wherever you found it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('f1c4ed48-8f6a-5fbf-bf59-ea8af2fe660e','Back again, <FirstName>! Did you bring me something with teeth?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('c4ae7c15-afc4-5020-9804-54761559835d','Do you have work for me?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('09cd4814-f445-59ae-8dbc-930e67e52df2','Bring me two wolf fangs. Skin the wolves around Avestrue; a furrier''s knife helps, and Owlstone sells one, as do I. White Fur herself has a fine pair, and more besides. I pay in silver, and in something better.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a1416c3c-02bf-59bb-8ff7-d791f6414bd8','Two wolf fangs. Consider it done.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ebd9c50e-aef8-515c-a1bb-ccf2cf307e7a','Splendid! Mind the white one. She is bigger than the stories.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a5723a5b-c1a9-57ba-94a4-93da5a1103f8','I have your wolf fangs.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('50015e0f-a2c8-57ea-9047-97befbc6a0f4','Beautiful fangs! Here: a necklace I made from the last pair, and some silver. And now that I know you can hunt, I have bigger plans for us. Oh, and between us: the chickens of Avestrue are not what they seem.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('c820d96a-a94b-51be-ad21-63759f27af66','Bigger plans?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('fab8f9e7-be67-53cb-bc46-88c77a6d3b3c','Five beasts, friend. Five legends every hunter tells at the fire, and nobody has a trophy of. A great boar, an old bear, a queen who croaks, a mother who glows, and one more I will not name until you are ready for her. Where exactly? If I knew, I would be rich. Bring me their trophies and I will make you talismans no king owns.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a2279359-0c46-57e5-a1e4-d9b5ce5035c2','I will hunt your legends.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('1a92004d-48ff-591d-bfdb-15324a8d2ba9','Ha! Then I had better start sharpening my tools. Bring them one at a time; each is a masterpiece.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a6f61adb-6f27-5ee9-84a9-c7876f3a6ffd','What else does a collector collect?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('1cb08e2a-3829-5681-aca9-b8e3ae027fb8','Everything that has ever made a town lock its doors! Thirteen of them. Some are closer than you think: in the city, under it, and in its water. Others you will meet only if your road goes far, and I think it will. I follow the hunters, so look for me wherever the game gets bigger. Bring me one trophy of each. Your journal will keep my riddles.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5dcd4651-b474-59db-8fbc-b4f41468fd21','Your Grand Collection. I will fill it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('4c982fba-4237-5baf-b3b1-5e033235866f','Then we shall be famous! Or eaten. Probably famous.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b9f39b87-15cc-5cad-b012-4b46ee4924d9','Any advice on finding your monsters?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('734d1eb8-38df-5f7e-8591-a030951eac31','Advice? Listen to frightened people. Wherever doors are locked at night and children are told not to go somewhere, one of my beasts is close. Start with the city, and keep your eyes open on the road. My riddles are in your journal.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a6241086-34cf-50b9-b84e-6890fa470bd1','Old Grimtusk is dead. I brought you this: Grimtusk''s Tusk.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e817ed74-b5c3-55cd-9739-7614ede2d745','Old Grimtusk! By Firun''s beard, you really did it. Give me a moment... there. The Grimtusk Charm. Wear it with pride.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('1b4df619-afd4-5ba2-ba63-3387d962f037','Ashpelt the Elder is dead. I brought you this: Ashpelt''s Claw.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d42f51a0-d8d6-5ce6-9b61-6429d3bb42c3','Ashpelt the Elder! By Firun''s beard, you really did it. Give me a moment... there. The Ashpelt''s Talisman. Wear it with pride.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8b5b543e-233e-56d8-8635-6cbd4bd6b3de','Queen of the Marsh is dead. I brought you this: Marsh Pearl.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('26cd3ee4-c7bc-5a2f-a4da-7900f9d40d94','Queen of the Marsh! By Firun''s beard, you really did it. Give me a moment... there. The Marsh Pearl Ring. Wear it with pride.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('34e9b5d9-09c9-526b-ba85-5bcbb3a7f20e','The Ember Queen is dead. I brought you this: Ember Crown.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('75734151-255c-56c0-99f6-56685445df36','The Ember Queen! By Firun''s beard, you really did it. Give me a moment... there. The Ember Crown Pendant. Wear it with pride.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('af879973-b136-5df9-a650-98a17963b182','The Broodmother is dead. I brought you this: Broodmother''s Heart.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a013d074-f5c0-5dea-be89-b92c272efe1b','The Broodmother! By Firun''s beard, you really did it. Give me a moment... there. The Broodmother''s Heart. Wear it with pride.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('dcad48a6-f40f-538e-b099-029805b212f7','For your Grand Collection: Mother Ratzinsky''s Iron Tooth.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('dd5219cb-3351-5aa0-a084-248171321e67','Oh! Oh, look at it. Into the collection it goes, with a label in my best hand. For you: the Rat-Queen''s Cameo, and a purse for the road.');
