INSERT INTO _Locale ("LocaId","LocaText") VALUES ('3920a220-7fb5-55b8-b1ba-f19c3e9f5ae7','Oh! Oh, look at it. Into the collection it goes, with a label in my best hand. For you: the Cyclops''-Eye Ring, and a purse for the road.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('edbc074c-652c-5f5b-9363-5345b1c1f44e','For your Grand Collection: Grolm King''s Crown-Shard.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('c8c9f505-1629-55f8-a647-e23ca166d639','Oh! Oh, look at it. Into the collection it goes, with a label in my best hand. For you: the Grolm King''s Signet, and a purse for the road.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b96d4847-ba40-586e-b8f7-d15f888c21ea','That was the last of your five legends.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('490d2f48-50ee-59d4-8904-1a977d7b2581','All five. Nobody will believe me, and I do not care. I kept a piece of each; this is the best thing I have ever made. Take it. The Heart of the Wild. And some gold, because legends still have to eat.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('9fd3bd1f-0163-5d95-bb82-7ed491636f39','That completes your Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('959f7fec-a327-51ae-9cb9-b15d568e7174','Complete. The Grand Collection of Ulfried Pelzfeld, and every piece in it brought by one hunter. I sewed a scrap of each into this mantle. Wear it, and every hunter from here to the deepest dwarf hall will know who you are.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('79793578-2cd6-560a-b7a4-611c1f0763ae','Show me your wares.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('46e8d191-4321-51df-9292-0d2ee9b3f985','Farewell, Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_ulfried_t','Ulfried Pelzfeld, Trophy Collector');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5f407e5e-d0f6-5d10-8623-91a0f05feac1','What a place! Everything within a day''s walk has bigger teeth than the last. I have not been this happy since my first wolf. What did you bring me?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d599d3e7-6aa3-5648-95ef-1d7eb2cc25e6','Back again, <FirstName>! Did you bring me something with teeth?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('6ce31cd5-f48d-5a2f-b78b-64fee73026a0','Do you have work for me?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d276f1dc-406a-529f-867d-0ab55dd6bd60','Bring me two wolf fangs. Skin the wolves around Avestrue; a furrier''s knife helps, and Owlstone sells one, as do I. White Fur herself has a fine pair, and more besides. I pay in silver, and in something better.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2fcf0a84-f212-521e-b8e4-b0a915762497','Two wolf fangs. Consider it done.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('212996bd-e461-54d1-acfb-1ceba37ef321','Splendid! Mind the white one. She is bigger than the stories.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('08aa24ce-7969-5c98-b433-1082ba7efde2','I have your wolf fangs.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e4d7e7d7-1929-56d2-8f72-d312f965e2d8','Beautiful fangs! Here: a necklace I made from the last pair, and some silver. And now that I know you can hunt, I have bigger plans for us. Oh, and between us: the chickens of Avestrue are not what they seem.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b6c84293-de04-56dd-949c-bff9e190cf1e','Bigger plans?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ae9003e2-fa64-5e5e-9baa-6fd80ba2ea21','Five beasts, friend. Five legends every hunter tells at the fire, and nobody has a trophy of. A great boar, an old bear, a queen who croaks, a mother who glows, and one more I will not name until you are ready for her. Where exactly? If I knew, I would be rich. Bring me their trophies and I will make you talismans no king owns.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('da3b7bf0-9c5e-534d-8c84-301f6b503dd1','I will hunt your legends.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2ea4f653-e40d-52ee-82f1-ed4a58bf5239','Ha! Then I had better start sharpening my tools. Bring them one at a time; each is a masterpiece.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('6bdd6a5b-e57c-5ad6-9c0f-ee81a3d5c453','What else does a collector collect?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('bbee79e7-7a13-5868-9cef-e26a7f6c5a00','Everything that has ever made a town lock its doors! Thirteen of them. Some are closer than you think: in the city, under it, and in its water. Others you will meet only if your road goes far, and I think it will. I follow the hunters, so look for me wherever the game gets bigger. Bring me one trophy of each. Your journal will keep my riddles.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e4698930-a163-56b5-8fa8-8c2484611b1b','Your Grand Collection. I will fill it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ef64465c-0cfa-516f-b7ba-d88b6a3a52e0','Then we shall be famous! Or eaten. Probably famous.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('66b89512-0c8d-5457-8e10-4433d55a30e8','Any advice on finding your monsters?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('9f550fa0-5b18-5237-993f-1ebcd89e8245','Advice? Listen to frightened people. Wherever doors are locked at night and children are told not to go somewhere, one of my beasts is close. Start with the city, and keep your eyes open on the road. My riddles are in your journal.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('39ddabd4-3726-5bee-ae15-8ec552a9d349','Old Grimtusk is dead. I brought you this: Grimtusk''s Tusk.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8c926f78-1c40-598a-8c68-c677eb51f767','Old Grimtusk! By Firun''s beard, you really did it. Give me a moment... there. The Grimtusk Charm. Wear it with pride.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('538ecec3-a6a7-590c-843d-53d9c9f2712a','Ashpelt the Elder is dead. I brought you this: Ashpelt''s Claw.');
