INSERT INTO _Locale ("LocaId","LocaText") VALUES ('94915a49-039b-55a6-b264-beee6deb0f12','For your Grand Collection: Cyclops Eye-Gem.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('83f303a4-3fd3-51ef-8049-77160ad5b4a4','Oh! Oh, look at it. Into the collection it goes, with a label in my best hand. For you: the Cyclops''-Eye Ring, and a purse for the road.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('18a57bc8-218a-518f-aa1a-c0aef93abad9','For your Grand Collection: Grolm King''s Crown-Shard.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5f12db06-0261-5688-a2f9-0f62fa5564b3','Oh! Oh, look at it. Into the collection it goes, with a label in my best hand. For you: the Grolm King''s Signet, and a purse for the road.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('c15cfac4-ce85-5d9e-af66-b7c304e94b75','That was the last of your five legends.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('6bcec5bd-5268-5fa8-b1f3-01615170e91d','All five. Nobody will believe me, and I do not care. I kept a piece of each; this is the best thing I have ever made. Take it. The Heart of the Wild. And some gold, because legends still have to eat.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a8bb1ec5-cade-52af-9478-5c56a0b326f3','That completes your Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8c2c5f35-4409-5598-9cb0-fe935204abb3','Complete. The Grand Collection of Ulfried Pelzfeld, and every piece in it brought by one hunter. I sewed a scrap of each into this mantle. Wear it, and every hunter from here to the deepest dwarf hall will know who you are.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('855313c2-cea7-57c5-862b-20aa9744de11','Show me your wares.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('29933e1f-6ce2-5c1f-88cf-d56d3a012883','Farewell, Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_ulfried_m','Ulfried Pelzfeld, Trophy Collector');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('822ec1c1-1380-5995-b6e4-5db747364f3d','The dwarves keep asking what I collect. ''Everything,'' I say, and they nod as if that were sensible. Show me your trophies, friend.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('0c3b825d-2e96-51f8-9a37-966a0032d679','Back again, <FirstName>! Did you bring me something with teeth?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8caaddbd-afd7-5fc1-8f1f-a07944870716','Do you have work for me?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('49452199-015b-5a2e-a312-9cb1c5bd6367','Bring me two wolf fangs. Skin the wolves around Avestrue; a furrier''s knife helps, and Owlstone sells one, as do I. White Fur herself has a fine pair, and more besides. I pay in silver, and in something better.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d6716ae9-fc83-5939-8209-5b23705cee4a','Two wolf fangs. Consider it done.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e8ca863a-fe83-5952-bed9-d4911266ffc9','Splendid! Mind the white one. She is bigger than the stories.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('4800272c-2872-5222-82ab-7ac858ecbde5','I have your wolf fangs.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('507932ba-b70e-5c6b-98fd-0eed1dcaa9f0','Beautiful fangs! Here: a necklace I made from the last pair, and some silver. And now that I know you can hunt, I have bigger plans for us. Oh, and between us: the chickens of Avestrue are not what they seem.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d2114e08-12f2-502f-b618-34c42a92e3dd','Bigger plans?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('79ea9847-05c8-5beb-a679-71e87ebdab69','Five beasts, friend. Five legends every hunter tells at the fire, and nobody has a trophy of. A great boar, an old bear, a queen who croaks, a mother who glows, and one more I will not name until you are ready for her. Where exactly? If I knew, I would be rich. Bring me their trophies and I will make you talismans no king owns.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('dd06f533-7cbf-5e4c-8b35-6cab16ca2956','I will hunt your legends.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5f1a8be4-143a-56f8-a9cc-497da5a3c7d1','Ha! Then I had better start sharpening my tools. Bring them one at a time; each is a masterpiece.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('7e13aab2-a362-52f9-a60d-855d6effce45','What else does a collector collect?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2b762872-e2ca-543e-a076-d6dbf2ee1d42','Everything that has ever made a town lock its doors! Thirteen of them. Some are closer than you think: in the city, under it, and in its water. Others you will meet only if your road goes far, and I think it will. I follow the hunters, so look for me wherever the game gets bigger. Bring me one trophy of each. Your journal will keep my riddles.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b0c614a1-0a42-5331-97fd-126cd9e37514','Your Grand Collection. I will fill it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e33be521-695e-5cce-965d-562f6b9ae64e','Then we shall be famous! Or eaten. Probably famous.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d68e339f-2b25-50ce-aa74-9decc8505335','Any advice on finding your monsters?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('64e5ed71-0001-53de-94f8-129d40f992f2','Advice? Listen to frightened people. Wherever doors are locked at night and children are told not to go somewhere, one of my beasts is close. Start with the city, and keep your eyes open on the road. My riddles are in your journal.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('12c949ce-bfd8-5a02-b74a-8d278c53dacd','Old Grimtusk is dead. I brought you this: Grimtusk''s Tusk.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b7f13d1a-68af-5d23-b12d-8fcdba399588','Old Grimtusk! By Firun''s beard, you really did it. Give me a moment... there. The Grimtusk Charm. Wear it with pride.');
