INSERT INTO _Locale ("LocaId","LocaText") VALUES ('9df76ffa-c1e0-52d6-9b19-ada04d2ab4f3','Oh! Oh, look at it. Into the collection it goes, with a label in my best hand. For you: the Grolm King''s Signet, and a purse for the road.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('544572d9-afce-57a9-bd48-c875612dd124','That was the last of your five legends.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('38e8e6b7-690e-5930-9ae6-8665f5930966','All five. Nobody will believe me, and I do not care. I kept a piece of each; this is the best thing I have ever made. Take it. The Heart of the Wild. And some gold, because legends still have to eat.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b58aacdf-71e8-509e-9168-69261e0d8b83','That completes your Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('4e863568-4d4f-5d3f-85e4-80a463309604','Complete. The Grand Collection of Ulfried Pelzfeld, and every piece in it brought by one hunter. I sewed a scrap of each into this mantle. Wear it, and every hunter from here to the deepest dwarf hall will know who you are.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('525dd6a4-885c-52ff-8c29-c2cfdc0cda93','Show me your wares.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('7cb02c36-529c-5973-a22a-e0defed7ce02','Farewell, Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('35a4291a-f097-5cc8-97f9-acb46ad61822','Teeth for the Collector');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('3a467b18-f0f2-556b-bac0-f68e5af75ae7','Ulfried Pelzfeld, a travelling trophy collector who follows the hunters, wants trophies from the local wolves.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5b4efc7f-b5ff-50d8-b30d-e1d300cb0b7a','Ulfried paid me well for the wolf fangs and hinted at bigger game.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('bd35f0a5-33d5-5737-be77-897b1f42eadc','Two Wolf Fangs');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e49f5a12-4c11-51c9-bb25-6faef4eedc9b','Bring Ulfried two Wolf Fangs. Skinning wolves (Animal Lore) yields fangs; the white wolf White Fur always carries a pair. Ulfried waits next to Owlstone in Avestrue, and later on Praios Square in Ferdok.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e472aeba-f80e-5acf-b3fe-b2086298b6c3','I gave Ulfried two Wolf Fangs.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('66e261bd-0951-5845-aad4-29ded542d684','Beasts of Legend');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('0b904ba5-8a14-5ee5-b579-f905f5914d7c','Ulfried wants trophies from five legendary beasts.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('4fb19321-8add-5f96-9c04-0225907c735d','All five legends are hunted. Ulfried made me the Heart of the Wild.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('c6dc42b5-7882-537b-97c6-e42c59598454','The Great Boar');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('dd24d315-10b3-5ebd-bd98-88793016c35e','A boar the size of a cart, scarred by a dozen hunters who did not come home, roams the hills where farmers fence their fields twice. Bring its trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ee58c68d-7f3a-58f0-bc9b-684c0a0dd11a','Ulfried has the trophy of Old Grimtusk.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('73e313f2-2f4e-5992-ace9-ecd949d8f576','The Grey Bear');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('01ccc4aa-502d-5d0f-a689-2741cd2ade05','The oldest bear alive sleeps somewhere dark and green, where even hunters walk quietly. Bring its trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('7d1335aa-445b-557d-9b78-ce8e5e6cfe03','Ulfried has the trophy of Ashpelt the Elder.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('46addb42-f4db-554a-89cd-5df50a581f15','The Croaking Queen');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('1b4ca103-fe26-583e-9875-b784ef0dde40','Somewhere wet and grey, a queen croaks louder than the bells, deep where the dead are buried last. Bring its trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('3904ae0f-f47a-50f1-afe0-1f8d0dfdd054','Ulfried has the trophy of Queen of the Marsh.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a2cff43c-6e49-5177-a005-4a224d8c873a','The Glowing Mother');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('c5ee0b0c-0c36-5862-8180-4680a48cae84','Where the small lights dance thickest at night, far from here, their mother nests in the warm dark. Bring its trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('526b7577-0361-50f4-9e81-efc9eb5b62a8','Ulfried has the trophy of The Ember Queen.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('3bd511b9-b3b1-5059-ac82-8069d888da5e','The Patient Mother');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e2eccc62-fd61-51fc-8ee5-8cd72c1acacf','Far beyond anywhere you have been, a mother guards her treasures in the dark. Only if you are mad. Bring its trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('fb331a0e-23e5-5e07-b0a8-335a9404bc77','Ulfried has the trophy of The Broodmother.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('bb618f2e-0069-5c82-a6f6-43f77ce7b5c7','The Grand Collection');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('21b96944-3dc0-510c-91c7-594d1b5b909a','Ulfried wants one trophy from every monster that ever made a town lock its doors. He follows the hunters, so look for him wherever the game gets bigger.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('6985c133-1be3-5f65-844f-8a09542311a1','The Grand Collection is complete. Ulfried gave me the Mantle of a Thousand Trophies.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('9659159c-df19-54f9-b50c-48cc33cfa1d4','The Mother Below');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2dd46194-8f30-585d-ae17-53aae2ceddb1','Something under the city breeds faster than the city can count. Find the one that started it. Bring the trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('bd33d50d-5172-5f2c-be5c-1b46a67858a0','Mother Ratzinsky''s Iron Tooth is in the Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('f2ca98e5-9f26-5ef7-bd90-843502174b81','The Tavern Pest');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('7f5b9fbf-832d-5b72-ac5c-5f309cf72e29','A tavern in the city has a cellar problem the innkeeper would rather not talk about. Bring the trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('63aa4a1d-f151-59c5-ab9f-9699157c6dfb','Carapace of the Gentle Sow is in the Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b4cde910-db3b-5215-adb3-52889e6af824','The Watcher Below');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d9e16678-95ed-5878-a20e-a3ec4e309291','Something lives beneath the place where people go to ask about the future. Bring the trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e815d6ad-4fb6-5854-90a6-446b286c63a5','Oracle Spider''s Eye is in the Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('125e0ba5-f3ff-5c3e-ba59-9876fc81ee25','The Harbour Terror');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('54e2549e-cfcd-5b44-9f83-595b5cbbe926','Fishermen whisper about something in the harbour water. Bring the trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('18c4b9aa-53c2-5ebe-8a54-d85895bddb9a','Marascan Crab Claw is in the Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('1ebc9c54-f49f-5e26-90f8-bf8bb0f1cddc','The Whispering Wood');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('72bf150c-4c57-56cd-b804-0d06d61d4590','Somewhere the ground is never dry, a tree whispers at night. Trees should not whisper. Bring the trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('66a27d93-50f3-5442-9112-bf538487219a','Heartwood of the Evil Tree is in the Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5c4cba15-fe7d-5ced-9dea-eb9a50e9c720','The Stubborn Dead');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('73079961-f94f-545d-9ff8-d9abdaee8c23','A beast of burden that refused to stay dead still walks somewhere it should not. Bring the trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('1754b6c7-dddb-5066-a4d8-a9a5ca91edb4','Bell of the Undead Mule is in the Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('c30361cb-fb93-5452-9a60-f0eae4eb7285','Something in the Vaults');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('0ede7e7a-822c-5626-a0c3-27c5f95efbcb','An old castle keeps something in its vaults, grown fat on whoever lives there now. Bring the trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b46a026c-7fd4-58aa-a995-a19b344da84b','Vault Spider''s Mandible is in the Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('6cb79520-83ce-529b-934c-ccdfbc0da926','The Old One');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e6bef848-49fd-5006-ac88-dfc8f70eae90','In caves you smell long before you see them, something very old is waiting. Bring the trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('940976fa-a0cb-5307-ad01-db3134c2f0c9','Linnorm''s Heart is in the Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('49cd36fa-afbd-5a9a-b3b4-ec6600af3c66','The Tusked Chief');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ae8a024c-a69c-529a-a496-ad8a268d66b6','Big, hungry folk have a chief who wears his tusks like a crown. Find their camp. Bring the trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2e837766-462b-5863-aaf3-8079944f6f44','Ogre Chief''s Tusk is in the Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('04b4957b-6a8a-53d8-a25d-84549ebd43ff','The Eye That Watches');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b63c2c4e-f5a2-51bd-b530-d68c6730ab0e','Every land has one creature nobody dares to name. If you ever meet it, bring me its eye. Bring the trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2c01b7ac-5015-50b7-9b2d-015cf94c24e9','Eye of Japhgur is in the Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('0cb0fbc8-8288-50a2-a543-3d50f25b73fb','The Moon-Mad Pack');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('23f04d18-fe48-571d-ab72-7eb37c48cbe4','Somewhere green and old, a whole pack of wolves lost its mind in a storm. Bring me the fang of the one that leads them. Bring the trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d844ed82-d8e4-5396-80a3-bf49539da421','Greymaw''s Fang is in the Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('1768fc38-e495-514f-bcb7-16e88b795e4e','The Spirit Below');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('01621b10-1ad2-5c52-92a3-df06f93b7c74','Deeper than any bear should go, a spirit of the forest still walks in the dark. Bring me its claw, if you can. Bring the trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b0dd82f6-b14d-590f-8be4-fd49e3131e9c','Claw of the Elder Spirit is in the Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('0481a445-0513-5598-82a6-a81bc0623681','The Singing Queen');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('0d698b06-a1bc-570c-9b97-a093d6129eb6','Where the winged women hunt in flocks, one of them is bigger than the rest, and sings before she strikes. Bring me her crown. Bring the trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('3e4ecd6e-cea3-5322-bce6-fc01d3814e4d','Harpy Queen''s Crown-Plume is in the Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('7905b0a0-a182-51c1-abd3-12712e9bd092','The Heart of Stone');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('435a4b2c-418e-5318-b58e-4277233a8335','Somewhere under the mountains, guardians still follow orders nobody gives any more. Bring me a heart of stone. Bring the trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('813a4da7-31df-5fae-8dd4-19ed1fc4e0e8','Golem Heartstone is in the Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('73337cfa-e6bd-55d0-91d1-c435ef1b7a39','The Old Bones');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('db277464-f65e-5294-89c7-437a8c2e78f9','In the oldest halls under the mountains lie bones nobody can name. Something precious was left among them. Bring the trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5ac1642f-daea-5d42-9551-fee24e5dd1e6','Cyclops Eye-Gem is in the Grand Collection.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('048270e5-eed6-53e2-86fd-f27ec3375972','The Hoarder''s Crown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('0cb8c79f-a9ce-584a-a217-c1c1172c7998','Small, greedy folk who haggle over everything have a king, and his chests hold a broken crown. Bring the trophy to Ulfried.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('52b3a165-d007-558f-a1b5-cc1f845a3f47','Grolm King''s Crown-Shard is in the Grand Collection.');
